def tarjan_scc(nodes, adj):
    """Iterative Tarjan SCC.

    nodes: iterable of node ids, adj: dict node -> list of (edge_id, target).
    Returns (comp_of, comps) where comp_of maps node -> component index and
    comps is a list of lists of nodes.
    """
    index = {}
    low = {}
    on_stack = set()
    stack = []
    comp_of = {}
    comps = []
    counter = 0
    for root in nodes:
        if root in index:
            continue
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        on_stack.add(root)
        work = [(root, iter(adj.get(root, ())))]
        while work:
            v, it = work[-1]
            descended = False
            for _eid, w in it:
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    on_stack.add(w)
                    work.append((w, iter(adj.get(w, ()))))
                    descended = True
                    break
                if w in on_stack and index[w] < low[v]:
                    low[v] = index[w]
            if descended:
                continue
            work.pop()
            if work:
                parent = work[-1][0]
                if low[v] < low[parent]:
                    low[parent] = low[v]
            if low[v] == index[v]:
                group = []
                while True:
                    w = stack.pop()
                    on_stack.discard(w)
                    comp_of[w] = len(comps)
                    group.append(w)
                    if w == v:
                        break
                comps.append(group)
    return comp_of, comps


def build_path(parent, target):
    """Edge ids of the tree path start -> target."""
    path = []
    cur = target
    while True:
        entry = parent.get(cur)
        if entry is None:
            break
        prev, eid = entry
        path.append(eid)
        cur = prev
    path.reverse()
    return path


def path_within(src, dst, adj, comp_of, cid):
    """Shortest path (edge ids) from src to dst inside one component."""
    if src == dst:
        return []
    prev = {src: None}
    queue = [src]
    head = 0
    while head < len(queue):
        v = queue[head]
        head += 1
        for eid, w in adj[v]:
            if comp_of.get(w) != cid:
