    for s in sorted(reach):
        blocked = False
        for nm in fair_names:
            if s in enabled.get(nm, ()):
                blocked = True
                break
        if not blocked:
            base["terminates"] = False
            base["liveness"] = {
                "prefix": build_path(pruned_parent, s),
                "loop": [-1],
            }
            return base

    base["terminates"] = True
    base["liveness"] = None
    return base


def handle_export(obj):
    inputs, p_count, r_count, d_count, n_states = validate_graph(obj)
    states = obj["states"]
    edges = obj["edges"]
    start = obj["start"]
    fairness = obj["fairness"]
    safe_states, done_states = compute_predicates(
        inputs, p_count, r_count, d_count, states
    )
    names = sorted({edge[1] for edge in edges} | {f["action"] for f in fairness})
    index = {name: i + 1 for i, name in enumerate(names)}
    edge_text = ",".join(
        "<<%d,%d,%d>>" % (edge[0], index[edge[1]], edge[2]) for edge in edges
    )
    action_text = ",".join('"%s"' % name for name in names)
    wf_ids = sorted(
        index[f["action"]] for f in fairness if f["mode"] == "weak"
    )
    sf_ids = sorted(
        index[f["action"]] for f in fairness if f["mode"] == "strong"
    )
    safe_text = ",".join(str(i) for i in range(n_states) if safe_states[i])
    done_text = ",".join(str(i) for i in range(n_states) if done_states[i])
    module = (
        "---- MODULE ModelData ----\n"
        "EXTENDS Integers, Sequences, FiniteSets\n"
        "Nodes == 0..%d\n"
        "Initial == %d\n"
        "Edges == {%s}\n"
        "ActionNames == <<%s>>\n"
        "WFIds == {%s}\n"
        "SFIds == {%s}\n"
        "SafeNodes == {%s}\n"
        "DoneNodes == {%s}\n"
        "====\n"
    ) % (
        n_states - 1,
        start,
        edge_text,
        action_text,
        ",".join(str(i) for i in wf_ids),
        ",".join(str(i) for i in sf_ids),
        safe_text,
        done_text,
    )
    config = (
        "SPECIFICATION Spec INVARIANT Safety PROPERTY Termination "
        "CHECK_DEADLOCK FALSE"
    )
    return {"module": module, "config": config}


def dispatch(obj):
    if not isinstance(obj, dict):
        raise SchemaError
    if "op" not in obj or "inputs" not in obj:
        raise SchemaError
    op = obj["op"]
    if not isinstance(op, str):
        raise SchemaError
    if op == "replay":
        return handle_replay(obj)
    if op == "audit":
        return handle_audit(obj)
    if op == "export":
        return handle_export(obj)
    raise SchemaError


def main():
    out = sys.stdout
    for raw in sys.stdin.buffer:
        if raw.endswith(b"\n"):
            raw = raw[:-1]
        if len(raw) > MAX_LINE_BYTES:
            response = {"error": "E_LIMIT"}
        else:
            try:
                text = raw.decode("utf-8")
            except UnicodeDecodeError:
                response = {"error": "E_JSON"}
            else:
                try:
                    obj = parse_json(text)
                except Exception:
                    response = {"error": "E_JSON"}
                else:
                    try:
                        response = dispatch(obj)
                    except SchemaError:
                        response = {"error": "E_SCHEMA"}
                    except LimitError:
                        response = {"error": "E_LIMIT"}
                    except RecursionError:
                        response = {"error": "E_LIMIT"}
                    except MemoryError:
                        response = {"error": "E_LIMIT"}
        out.write(json.dumps(response, separators=(",", ":")))
        out.write("\n")
    out.flush()


if __name__ == "__main__":
    main()
